// Copia en JavaScript de mmss de Senda (src/util/fechas.ts), sin los tipos de TypeScript
function mmss(ms) {
  const s = Math.max(0, Math.ceil(ms / 1000));
  return `${Math.floor(s / 60)}:${`${s % 60}`.padStart(2, "0")}`;
}
